SELECT ?stadiumName
WHERE {
  ?stadium rdf:type :stadium .
  ?stadium :stadium\#name ?stadiumName .
  FILTER NOT EXISTS {
    ?concert rdf:type :concert .
    ?concert :concert\#ref-stadium_id ?stadium .
  }
}

SELECT ?stadiumName
WHERE {
  ?stadium rdf:type :stadium .
  ?stadium :stadium\#name ?stadiumName .
  FILTER NOT EXISTS {
    ?concert rdf:type :concert .
    ?concert :concert\#ref-stadium_id ?stadium .
  }
}

SELECT DISTINCT ?country
WHERE {
  {
    ?singer :singer\#age ?age .
    ?singer :singer\#country ?country .
    FILTER (?age > 40)
  }
  INTERSECT
  {
    ?singer2 :singer\#age ?age2 .
    ?singer2 :singer\#country ?country2 .
    FILTER (?age2 < 30)
  }
}

SELECT ?stadiumName
WHERE {
  ?stadium rdf:type :stadium .
  ?stadium :stadium\#name ?stadiumName .
  FILTER NOT EXISTS {
    ?concert rdf:type :concert .
    ?concert :concert\#year "2014" .
    ?concert :concert\#ref-stadium_id ?stadium .
