SELECT ?concertName ?theme (COUNT(?singer) AS ?numSingers)
WHERE {
  ?concert :concert\#concert_name ?concertName ;
           :concert\#theme ?theme ;
           :concert\#concert_id ?concertId .
  ?singerInConcert :singer_in_concert\#ref-concert_id ?concert ;
                   :singer_in_concert\#ref-singer_id ?singer .
}
GROUP BY ?concertName ?theme

SELECT (COUNT(?concert) AS ?numConcerts)
WHERE {
  ?stadium :stadium\#capacity ?capacity .
  ?concert :concert\#ref-stadium_id ?stadium .
  FILTER (?capacity = (
    SELECT (MAX(?maxCapacity) AS ?maxCapacity)
    WHERE {
      ?stadium :stadium\#capacity ?maxCapacity .
    }
  ))
}

SELECT (COUNT(?concert) AS ?concertCount)
WHERE {
  ?stadium :stadium\#capacity ?capacity .
  ?concert :concert\#ref-stadium_id ?stadium .
  FILTER (?capacity = (
    SELECT (MAX(?maxCapacity) AS ?maxCapacity)
    WHERE {
      ?stadium :stadium\#capacity ?maxCapacity .
    }
  ))
}
